def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    edges = [
        [grid[0][c] for c in range(w)],
        [grid[h - 1][c] for c in range(w)],
        [grid[r][0] for r in range(h)],
        [grid[r][w - 1] for r in range(h)],
    ]
    horizontal_edge_counts = sum(v != bg for edge in edges[:2] for v in edge)
    vertical_edge_counts = sum(v != bg for edge in edges[2:] for v in edge)
    horizontal_bars = horizontal_edge_counts >= vertical_edge_counts

    boundary_counts = Counter(v for edge in edges for v in edge if v != bg)
    bar = boundary_counts.most_common(1)[0][0]
    marks = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != bar]
    mark_color = Counter(grid[r][c] for r, c in marks).most_common(1)[0][0]

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            if values[i] != bar:
                i += 1
                continue
            j = i
            while j + 1 < len(values) and values[j + 1] == bar:
                j += 1
            result.append((i, j))
            i = j + 1
        return result

    if horizontal_bars:
        sides = [
            (0, runs(grid[0])),
            (h - 1, runs(grid[h - 1])),
        ]
        along = lambda p: p[1]
    else:
        sides = [
            (0, runs([grid[r][0] for r in range(h)])),
            (w - 1, runs([grid[r][w - 1] for r in range(h)])),
        ]
        along = lambda p: p[0]

    # Use the longest border run on each of the opposite edges.
    segs = []
    for edge_pos, intervals in sides:
        lo, hi = max(intervals, key=lambda x: x[1] - x[0])
        segs.append((edge_pos, lo, hi))

    def segment_score(seg):
        _, lo, hi = seg
        return sum(lo <= along(p) <= hi for p in marks)

    source_i = max(range(2), key=lambda i: segment_score(segs[i]))
    source = segs[source_i]
    target = segs[1 - source_i]
    out = [row[:] for row in grid]

    # Project marker positions onto the opposite border segment and fill
    # the full lines connecting the two sides.
    _, slo, shi = source
    _, tlo, thi = target
    for r, c in marks:
        offset = along((r, c)) - slo
        if not (0 <= offset <= shi - slo):
            continue
        u = tlo + offset
        if u > thi:
            continue
        if horizontal_bars:
            for rr in range(h):
                if out[rr][u] != bar:
                    out[rr][u] = mark_color
        else:
            for cc in range(w):
                if out[u][cc] != bar:
                    out[u][cc] = mark_color

    # Extend each marker toward the border segment it aligns with.
    edge_pos = source[0]
    for r, c in marks:
        u = along((r, c))
        if not (slo <= u <= shi):
            continue
        perp = r if horizontal_bars else c
        step = 1 if edge_pos < perp else -1
        pos = edge_pos + step
        while pos != perp:
            if horizontal_bars:
                out[pos][c] = mark_color
            else:
                out[r][pos] = mark_color
            pos += step

    for r, c in marks:
        out[r][c] = 4
    return out
